#pragma once
#include <fstream>
#include <unordered_map>
#include <set>
#include <vector>
#include <string>
#include <string_view>
#include <sstream>
#include <stdexcept>
#include <algorithm>
#include <cctype>

namespace detail {
    inline bool is_space(char c) { return std::isspace(static_cast<unsigned char>(c)); }
    inline std::string trim(const std::string& s) {
        auto start = s.begin();
        while (start != s.end() && is_space(*start)) ++start;
        auto end = s.end();
        do { --end; } while (std::distance(start, end) > 0 && is_space(*end));
        return std::string(start, end + 1);
    }
    inline std::string rtrim(const std::string& s) {
        auto end = s.end();
        do { --end; } while (std::distance(s.begin(), end) > 0 && is_space(*end));
        return std::string(s.begin(), end + 1);
    }
    inline size_t find_char_or_comment(std::string_view sv, char ch) {
        for (size_t i = 0; i < sv.size(); ++i) {
            if (sv[i] == ';' || sv[i] == '#') return i;
            if (sv[i] == ch) return i;
        }
        return std::string_view::npos;
    }
    template<typename T>
    inline bool parse_value(std::string_view sv, T& out) {
        std::istringstream iss(std::string(sv));
        return (iss >> out) && iss.eof();
    }
}

class INIReader {
public:
    INIReader() = default;
    explicit INIReader(const std::string& filename) { ParseFile(filename); }
    explicit INIReader(std::FILE* file) { ParseFile(file); }

    int ParseError() const noexcept { return _error; }

    std::set<std::string> Sections() const {
        std::set<std::string> result;
        for (const auto& [section, _] : _values) result.insert(section);
        return result;
    }

    std::set<std::string> Keys(const std::string& section) const {
        const auto* sec = GetSection(section);
        std::set<std::string> result;
        for (const auto& [key, _] : *sec) result.insert(key);
        return result;
    }

    std::unordered_map<std::string, std::string> Get(const std::string& section) const {
        const auto* sec = GetSection(section);
        std::unordered_map<std::string, std::string> result;
        for (const auto& [key, val] : *sec) result[key] = val;
        return result;
    }

    template<typename T>
    T Get(const std::string& section, const std::string& name) const {
        const auto* sec = GetSection(section);
        const auto it = sec->find(name);
        if (it == sec->end()) throw std::runtime_error("Key not found: " + name);
        T result;
        if (!detail::parse_value(it->second, result)) {
            throw std::runtime_error("Conversion failed for key: " + name);
        }
        return result;
    }

    template<typename T>
    T Get(const std::string& section, const std::string& name, const T& default_v) const noexcept {
        try { return Get<T>(section, name); } catch (...) { return default_v; }
    }

    template<typename T>
    std::vector<T> GetVector(const std::string& section, const std::string& name) const {
        const auto* sec = GetSection(section);
        const auto it = sec->find(name);
        if (it == sec->end()) throw std::runtime_error("Key not found: " + name);
        std::vector<T> result;
        std::istringstream iss(it->second);
        T val;
        while (iss >> val) result.push_back(val);
        return result;
    }

    template<typename T>
    std::vector<T> GetVector(const std::string& section, const std::string& name, const std::vector<T>& default_v) const noexcept {
        try { return GetVector<T>(section, name); } catch (...) { return default_v; }
    }

    template<typename T>
    void InsertEntry(const std::string& section, const std::string& name, const T& v) {
        auto& sec = _values[section];
        if (sec.find(name) != sec.end()) throw std::runtime_error("Duplicate key: " + name);
        sec[name] = V2String(v);
    }

    template<typename T>
    void UpdateEntry(const std::string& section, const std::string& name, const T& v) {
        auto& sec = _values[section];
        if (sec.find(name) == sec.end()) throw std::runtime_error("Key not found: " + name);
        sec[name] = V2String(v);
    }

protected:
    int _error{0};
    std::unordered_map<std::string, std::unordered_map<std::string, std::string>> _values;

private:
    static bool BoolConverter(std::string_view sv) {
        const auto s = detail::trim(sv);
        if (s == "1" || s == "true" || s == "TRUE" || s == "True") return true;
        if (s == "0" || s == "false" || s == "FALSE" || s == "False") return false;
        throw std::runtime_error("Invalid boolean value: " + std::string(sv));
    }

    template<typename T>
    static std::string V2String(const T& v) {
        if constexpr (std::is_same_v<T, bool>) return BoolConverter(v) ? "true" : "false";
        else {
            std::ostringstream oss; oss << v; return oss.str();
        }
    }

    template<typename T>
    static std::string Vec2String(const std::vector<T>& vs) {
        if (vs.empty()) return "";
        std::ostringstream oss;
        for (size_t i = 0; i < vs.size(); ++i) {
            if (i > 0) oss << ' ';
            oss << V2String(vs[i]);
        }
        return oss.str();
    }

    const std::unordered_map<std::string, std::string>* GetSection(const std::string& section) const {
        const auto it = _values.find(section);
        if (it == _values.end()) throw std::runtime_error("Section not found: " + section);
        return &it->second;
    }

    std::unordered_map<std::string, std::string>& FindEntry(const std::string& section, const std::string& name) {
        auto& sec = _values[section];
        if (sec.find(name) == sec.end()) throw std::runtime_error("Key not found: " + name);
        return sec[name];
    }

    void ParseFile(const std::string& filename) {
        std::ifstream file(filename, std::ios::binary | std::ios::ate);
        if (!file) { _error = -1; throw std::runtime_error("File not found: " + filename); }
        const auto size = file.tellg();
        file.seekg(0, std::ios::beg);
        std::string content(size, '\0');
        if (!file.read(&content[0], size)) { _error = -2; throw std::runtime_error("Memory allocation error"); }
        Parse(content);
    }

    void ParseFile(std::FILE* file) {
        if (!file) { _error = -1; throw std::runtime_error("Invalid FILE pointer"); }
        fseek(file, 0, SEEK_END);
        const auto size = ftell(file);
        fseek(file, 0, SEEK_SET);
        std::string content(size, '\0');
        if (fread(&content[0], 1, size, file) != static_cast<size_t>(size)) { _error = -2; throw std::runtime_error("Memory allocation error"); }
        Parse(content);
    }

    void Parse(std::string content) {
        if (content.size() >= 3 && static_cast<unsigned char>(content[0]) == 0xEF && 
            static_cast<unsigned char>(content[1]) == 0xBB && static_cast<unsigned char>(content[2]) == 0xBF) {
            content.erase(0, 3);
        }
        std::string current_section;
        size_t line_no = 0;
        for (std::string_view sv : detail::split_lines(content)) {
            ++line_no;
            if (sv.empty()) continue;
            const auto pos = detail::find_char_or_comment(sv, '=');
            if (pos == std::string_view::npos) {
                const auto trimmed = detail::trim(sv);
                if (!trimmed.empty() && (trimmed[0] != ';' && trimmed[0] != '#')) {
                    if (trimmed.back() == ']') {
                        current_section = std::string(trimmed.substr(1, trimmed.size() - 2));
                        _values[current_section];
                    }
                }
            } else {
                const auto key = detail::rtrim(std::string(sv.substr(0, pos)));
                const auto val = std::string(sv.substr(pos + 1));
                if (current_section.empty()) { _error = static_cast<int>(line_no); throw std::runtime_error("Key outside section"); }
                auto& sec = _values[current_section];
                if (sec.find(key) != sec.end()) { _error = static_cast<int>(line_no); throw std::runtime_error("Duplicate key: " + key); }
                sec[key] = val;
            }
        }
    }
};
